class Bathroom {
    public synchronized void use() {
        String name = Thread.currentThread().getName();
        System.out.println(name + " has entered the bathroom");

        try {
            Thread.sleep(5000);
            System.out.println(name + " is using the bathroom");
            Thread.sleep(5000);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        System.out.println(name + " has exited the bathroom");
    }
}

class Boy extends Thread {
    private Bathroom bathroom;
    Boy(Bathroom bathroom) {
        this.bathroom = bathroom;
    }
    @Override
    public void run() {
        bathroom.use();
    }
}

class Girl extends Thread {
    private Bathroom bathroom;
    Girl(Bathroom bathroom) {
        this.bathroom = bathroom;
    }
    @Override
    public void run() {
        bathroom.use();
    }
}

class Other extends Thread {
    private Bathroom bathroom;
    Other(Bathroom bathroom) {
        this.bathroom = bathroom;
    }
    @Override
    public void run() {
        bathroom.use();
    }
}

public class ThreadSynchronizationDemo {
    public static void main(String[] args) {
        Bathroom bathroom = new Bathroom();

        Boy boy = new Boy(bathroom);
        Girl girl = new Girl(bathroom);
        Other other = new Other(bathroom);

        boy.setName("Boy");
        girl.setName("Girl");
        other.setName("Other");

        boy.start();
        girl.start();
        other.start();
    }
}

